class InstalledPackage {
  InstalledPackage({
    this.packages,
    this.total,
  });

  static Future<InstalledPackage> list() async {
    DsmResponse res = await Api.dsm.entry(
      "SYNO.Core.Package",
      "list",
      parser: InstalledPackage.fromJson,
      version: 2,
      data: {
        "additional": jsonEncode([
          "description",
          "description_enu",
          "dependent_packages",
          "beta",
          "distributor",
          "distributor_url",
          "maintainer",
          "maintainer_url",
          "dsm_apps",
          "dsm_app_page",
          "dsm_app_launch_name",
          "report_beta_url",
          "support_center",
          "startable",
          "installed_info",
          "support_url",
          "is_uninstall_pages",
          "install_type",
          "autoupdate",
          "silent_upgrade",
          "installing_progress",
          "ctl_uninstall",
          "updated_at",
          "status",
          "url",
          "available_operation"
        ]),
      },
    );
    return res.data;
  }

  InstalledPackage.fromJson(dynamic json) {
    if (json['packages'] != null) {
      packages = [];
      json['packages'].forEach((v) {
        packages?.add(InstalledPackageItem.fromJson(v));
      });
    }
    total = json['total'];
  }
  List<InstalledPackageItem>? packages;
  num? total;
  InstalledPackage copyWith({
    List<InstalledPackageItem>? packages,
    num? total,
  }) =>
      InstalledPackage(
        packages: packages ?? this.packages,
        total: total ?? this.total,
      );
  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    if (packages != null) {
      map['packages'] = packages?.map((v) => v.toJson()).toList();
    }
    map['total'] = total;
    return map;
  }
}

