class InstalledPackageItem {
  InstalledPackageItem({
    this.additional,
    this.id,
    this.name,
    this.timestamp,
    this.version,
  });

  static Future<InstalledPackageItem> get(String id) async {
    DsmResponse res = await Api.dsm.entry(
      "SYNO.Core.Package",
      "get",
      parser: InstalledPackageItem.fromJson,
      version: 1,
      data: {
        "id": '"$id"',
        "additional": jsonEncode(["uninstall_pages"]),
      },
    );
    return res.data;
  }

  Future<bool?> start() async {
    DsmResponse res = await Api.dsm.entry("SYNO.Core.Package.Control", "start", version: 1, data: {
      "id": id,
      "dsm_apps": jsonEncode([additional?.dsmApps]),
    });
    return res.success;
  }

  Future<bool?> stop() async {
    DsmResponse res = await Api.dsm.entry("SYNO.Core.Package.Control", "stop", version: 1, data: {
      "id": id,
    });
    return res.success;
  }

  Future<bool?> uninstall({Map? extra}) async {
    DsmResponse res = await Api.dsm.entry("SYNO.Core.Package.Uninstallation", "uninstall", version: 1, data: {
      "id": id,
      "dsm_apps": additional?.dsmApps,
      if (extra != null) "extra_values": jsonEncode(extra),
    });
    return res.success;
  }

  InstalledPackageItem.fromJson(dynamic json) {
    additional = json['additional'] != null ? Additional.fromJson(json['additional']) : null;
    id = json['id'];
    name = json['name'];
    timestamp = json['timestamp'];
    version = json['version'];
  }
  Additional? additional;
  String? id;
  String? name;
  num? timestamp;
  String? version;
  bool canUpdate = false;
  InstalledPackageItem copyWith({
    Additional? additional,
    String? id,
    String? name,
    num? timestamp,
    String? version,
  }) =>
      InstalledPackageItem(
        additional: additional ?? this.additional,
        id: id ?? this.id,
        name: name ?? this.name,
        timestamp: timestamp ?? this.timestamp,
        version: version ?? this.version,
      );
  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    if (additional != null) {
      map['additional'] = additional?.toJson();
    }
    map['id'] = id;
    map['name'] = name;
    map['timestamp'] = timestamp;
    map['version'] = version;
    return map;
  }
}

